   virtual size_t    GetPath(char16_t* pPath16, size_t nPathLength);            virtual size_t    GetPath(char32_t* pPath32, size_t nPathCapacity);            virtual bool      Open(int nAccessFlags = kAccessFlagRead, int nCreationDisposition = kCDDefault, int nSharing = kShareRead, int nUsageHints = kUsageHintNone);             virtual bool      Close();            virtual uint32_t  GetType() const { return kTypeFileStream; }            virtual int       GetAccessFlags() const;            virtual int       GetState() const;            virtual size_type GetSize() const;            virtual bool      SetSize(size_type size);            virtual off_type  GetPosition(PositionType positionType = kPositionTypeBegin) const;            virtual bool      SetPosition(off_type position, PositionType positionType = kPositionTypeBegin);            virtual size_type GetAvailable() const;            virtual size_type Read(void* pData, size_type nSize);            virtual bool      Write(const void* pData, size_type nSize);            virtual bool      Flush();        protected:            typedef EA::IO::Path::PathString8 PathString8;            enum InternalStreamType            {                IST_FS,                IST_SAVE,                IST_SAVE_COMMON,            };            void                        Constructor();            bool                        VerifyHandles() const;                        FSFileHandle                mhFile;            PathString8                 mPath8;                         /// Path for the file.            int                         mnRefCount;                     /// Reference count, which may or may not be in use.            int                         mnAccessFlags;                  /// See enum AccessFlags.            mutable FSError             mnLastError;                    /// Used for error reporting.            FSStat                      mStat;                          /// Used to track file size, etc            static const size_type      mBufferSize = 64*1024;          /// Buffer size for reading/writing            char                        *mpReadBuffer;                  /// Used for read buffer alignment            char                        *mpWriteBuffer;                 /// Uesd for write buffer aligment            InternalStreamType          mStreamType;                    /// Used internally to control how stream is accessed.        }; // class FileStream    } // namespace IO} // namespace EA#endif  // #ifndef EAIO_EAFILESTREAMS_CAFE_H